macro_rules! HasEscapingVarsVisitor {
    () => {
        # [doc = " An \"escaping var\" is a bound var whose binder is not part of `t`. A bound var can be a"] # [doc = " bound region or a bound type."] # [doc = ""] # [doc = " So, for example, consider a type like the following, which has two binders:"] # [doc = ""] # [doc = "    for<'a> fn(x: for<'b> fn(&'a isize, &'b isize))"] # [doc = "    ^~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ outer scope"] # [doc = "                  ^~~~~~~~~~~~~~~~~~~~~~~~~~~~  inner scope"] # [doc = ""] # [doc = " This type has *bound regions* (`'a`, `'b`), but it does not have escaping regions, because the"] # [doc = " binders of both `'a` and `'b` are part of the type itself. However, if we consider the *inner"] # [doc = " fn type*, that type has an escaping region: `'a`."] # [doc = ""] # [doc = " Note that what I'm calling an \"escaping var\" is often just called a \"free var\". However,"] # [doc = " we already use the term \"free var\". It refers to the regions or types that we use to represent"] # [doc = " bound regions or type params on a fn definition while we are type checking its body."] # [doc = ""] # [doc = " To clarify, conceptually there is no particular difference between"] # [doc = " an \"escaping\" var and a \"free\" var. However, there is a big"] # [doc = " difference in practice. Basically, when \"entering\" a binding"] # [doc = " level, one is generally required to do some sort of processing to"] # [doc = " a bound var, such as replacing it with a fresh/placeholder"] # [doc = " var, or making an entry in the environment to represent the"] # [doc = " scope to which it is attached, etc. An escaping var represents"] # [doc = " a bound var for which this processing has not yet been done."] struct HasEscapingVarsVisitor { # [doc = " Anything bound by `outer_index` or \"above\" is escaping."] outer_index : ty :: DebruijnIndex , }
    };
}

HasEscapingVarsVisitor!();